package com.mrgregles.bsp_core.shop;

/**
 * The Market Stall skins, in the designer's order, with the overlay points of each model in model units
 * (1/16 block, front facing north): the stock lamp and open lamp faces as x0, y0, x1, y1, z; the display
 * item's centre and its width in blocks; then the matching Stall Display's item centre and its GROUND-context scale.
 *
 * GENERATED by tools/gen_stall_assets.py from tools/stall/layout.json. Do not edit.
 */
public enum StallSkin implements net.minecraft.util.StringRepresentable {
    FANTASY("fantasy", new float[]{0f, 13.25f, 2f, 15.25f, -0.5f}, new float[]{14f, 13.25f, 16f, 15.25f, -0.5f}, new float[]{8f, 16.25f, 6f}, 0.4f, false, new float[]{8f, 17f, 8f}, 0.875f),
    SCIFI("scifi", new float[]{3f, 8.5f, 5f, 10.5f, 1f}, new float[]{6f, 8.5f, 8f, 10.5f, 1f}, new float[]{8f, 17.25f, 8f}, 0.45f, true, new float[]{8f, 17.5f, 8f}, 0.875f),
    STEAMPUNK("steampunk", new float[]{1.5f, 8.25f, 3.5f, 10.25f, 1.25f}, new float[]{6f, 8.25f, 8f, 10.25f, 1.25f}, new float[]{5.5f, 16.25f, 6.25f}, 0.375f, true, new float[]{8f, 12.25f, 8f}, 0.688f),
    VANILLA("vanilla", new float[]{0f, 14f, 2f, 16f, 0.5f}, new float[]{14f, 14f, 16f, 16f, 0.5f}, new float[]{8f, 16.5f, 7f}, 0.45f, false, new float[]{8f, 18.5f, 8f}, 0.875f),
    NETHER("nether", new float[]{0.25f, 13f, 2.25f, 15f, 1.5f}, new float[]{13.75f, 13f, 15.75f, 15f, 1.5f}, new float[]{8f, 16.75f, 8.5f}, 0.45f, true, new float[]{8f, 16.5f, 7.5f}, 0.812f),
    YATAI("yatai", new float[]{0.5f, 13f, 2f, 15f, 1.25f}, new float[]{14f, 13f, 15.5f, 15f, 1.25f}, new float[]{8f, 16f, 8f}, 0.4f, true, new float[]{8f, 12.5f, 7f}, 0.688f),
    NAUTICAL("nautical", new float[]{3f, 8f, 5f, 10f, 4.25f}, new float[]{11f, 8f, 13f, 10f, 4.25f}, new float[]{8f, 16.25f, 7f}, 0.45f, true, new float[]{8f, 16f, 7f}, 0.875f),
    ARCANE("arcane", new float[]{2f, 8f, 4f, 10f, 2f}, new float[]{12f, 8f, 14f, 10f, 2f}, new float[]{8f, 17.75f, 8.5f}, 0.45f, true, new float[]{8f, 16.5f, 8f}, 0.75f);

    public final String id;
    /** x0, y0, x1, y1, z of the lamp face, model units. */
    public final float[] stockLamp, openLamp;
    /** The display item's centre, model units. */
    public final float[] item;
    /** The display item's width in blocks. */
    public final float itemScale;
    /** Whether the whole model glows (the lower half then gives light). */
    public final boolean lit;
    /** The Stall Display of this skin: its floating item's centre (model units) and the GROUND-context scale that fits it. */
    public final float[] displayItem;
    public final float displayScale;

    StallSkin(String id, float[] stockLamp, float[] openLamp, float[] item, float itemScale, boolean lit, float[] displayItem, float displayScale) {
        this.id = id;
        this.stockLamp = stockLamp;
        this.openLamp = openLamp;
        this.item = item;
        this.itemScale = itemScale;
        this.lit = lit;
        this.displayItem = displayItem;
        this.displayScale = displayScale;
    }

    public StallSkin next() {
        return values()[(ordinal() + 1) % values().length];
    }

    public static StallSkin byId(String id) {
        for (StallSkin s : values()) {
            if (s.id.equals(id)) {
                return s;
            }
        }
        return VANILLA;
    }

    @Override
    public String getSerializedName() {
        return id;
    }
}
